<span class="line"><span style="color:#ABB2BF;">                l1 </span><span style="color:#56B6C2;">=</span><span style="color:#E5C07B;"> l1</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">next</span><span style="color:#ABB2BF;">;</span></span>
